let quoteDraft=safeLoad('sigma-quote-draft',{kind:'health',customer:'',phone:'',city:'',caseType:'Fresh',sumInsured:'1000000',members:[{name:'',relation:'Self',age:''}],plans:[],note:'',variant:'Elite',pa:500000,port:false,portDetails:'',premiums:Array.from({length:8},()=>[0,0,0,0,0]),screenshots:[]});
const nivaComponents=['Base Premium','WellConsult+ (OPD)','Claim Safeguard+','Annual Health Check-Up','Personal Accident','Zonal Loading','Vintage Discount','Discount in Lieu of Commission'];
function saveQuoteDraft(){if(globalThis.sigmaSaveWorkspace?.())return;localStorage.setItem('sigma-quote-draft',JSON.stringify(quoteDraft))}
function quoteField(key,value){quoteDraft[key]=value;saveQuoteDraft()}
function quoteMembers(){return `<div id="quoteMembers">${quoteDraft.members.map((m,i)=>`<div class="quote-member"><label class="field">Name<input aria-label="Insured ${i+1} name" value="${esc(m.name)}" oninput="quoteDraft.members[${i}].name=this.value;saveQuoteDraft()"></label><label class="field">Relation<select onchange="quoteDraft.members[${i}].relation=this.value;saveQuoteDraft()">${optionsHTML(['Self','Spouse','Son','Daughter','Father','Mother','Father-in-law','Mother-in-law','Other'],m.relation,false)}</select></label><label class="field">Date of birth<input type="date" value="${esc(m.dob||'')}" onchange="setQuoteDOB(${i},this.value)"></label><label class="field">Age<input type="number" min="0" max="120" aria-label="Insured ${i+1} age" value="${esc(m.age)}" oninput="quoteDraft.members[${i}].age=this.value;saveQuoteDraft()"></label><label class="field">PED (if any)<input value="${esc(m.ped||'')}" oninput="quoteDraft.members[${i}].ped=this.value;saveQuoteDraft()"></label><button class="quiet" aria-label="Remove insured ${i+1}" onclick="quoteDraft.members.splice(${i},1);saveQuoteDraft();render()">${I('close')}</button></div>`).join('')}</div>${btn('Add member',"quoteDraft.members.push({name:'',relation:'Spouse',age:''});saveQuoteDraft();render()",'plus')}`}
function setQuoteDOB(i,value){quoteDraft.members[i].dob=value;let d=new Date(value),now=new Date();if(Number.isFinite(+d)){quoteDraft.members[i].age=now.getFullYear()-d.getFullYear()-(now.getMonth()<d.getMonth()||now.getMonth()===d.getMonth()&&now.getDate()<d.getDate()?1:0)}saveQuoteDraft();render()}
function quoteCustomerFields(){return `<div class="formgrid"><label class="field">Customer name *<input value="${esc(quoteDraft.customer)}" required oninput="quoteField('customer',this.value)"></label><label class="field">Mobile *<input type="tel" value="${esc(quoteDraft.phone)}" oninput="quoteField('phone',this.value)"></label><label class="field">City<input value="${esc(quoteDraft.city)}" oninput="quoteField('city',this.value)"></label><label class="field">Quote ref<input value="${esc(quoteDraft.reference||'')}" oninput="quoteField('reference',this.value)"></label><label class="field">Case type<select onchange="quoteField('caseType',this.value)">${optionsHTML(['Fresh','Port','Renewal'],quoteDraft.caseType,false)}</select></label><label class="field">Sum assured (₹)<input value="${esc(quoteDraft.sumInsured)}" oninput="quoteField('sumInsured',this.value)"></label></div>`}
function openHealthQuote(leadId){let l=db.leads.find(l=>l.id===leadId);if(l){quoteDraft.customer=l.name;quoteDraft.phone=l.phone;quoteDraft.city=l.city||'';saveQuoteDraft()}go('quotes')}
quotes=function(){return heading('HEALTH QUOTE','Health insurance comparison','Enter verified plan details and premiums. Draft is saved automatically.',btn('Saved quotes',"go('savedquotes')",'file'))+connectionNote()+`<div class="quote-editor"><section class="card pad"><h2>Customer details</h2>${quoteCustomerFields()}<h2 class="form-section">Insured members</h2>${quoteMembers()}</section><section class="card pad"><div class="sectiontitle"><h2>Select plans & premium inputs</h2>${btn('Add plan','quotePlanEditor()','plus',true)}</div><p class="subtle">Add insurer-verified premiums. No premium is inferred from age or coverage.</p>${quoteDraft.plans.length?`<div class="tablewrap"><table><thead><tr><th>Plan / sum assured</th><th>1 year</th><th>2 years</th><th>3 years</th><th></th></tr></thead><tbody>${quoteDraft.plans.map((p,i)=>`<tr><td><strong>${esc(p.insurer)} · ${esc(p.name)}</strong><br><input aria-label="Sum assured for ${esc(p.name)}" value="${esc(p.sumInsured||quoteDraft.sumInsured)}" oninput="quoteDraft.plans[${i}].sumInsured=this.value;saveQuoteDraft()"></td>${[0,1,2].map(y=>`<td><input type="number" min="0" step="0.01" aria-label="${esc(p.name)} ${y+1} year premium" value="${amount(p.premiums?.[y])}" oninput="quoteDraft.plans[${i}].premiums[${y}]=amount(this.value);saveQuoteDraft()"></td>`).join('')}<td>${btn('Edit features',`quotePlanEditor(${i})`,'file')}<button class="quiet" aria-label="Remove plan" onclick="quoteDraft.plans.splice(${i},1);saveQuoteDraft();render()">${I('close')}</button></td></tr>`).join('')}</tbody></table></div>`:emptyCard('No plans selected','Add up to 4 plans to build a comparison.')}<label class="field form-section">Advisor note<textarea rows="3" oninput="quoteField('note',this.value)">${esc(quoteDraft.note)}</textarea></label><div class="toolbar">${btn('Create note from quote data','makeQuoteNote()','file')}${btn('Preview comparison',"previewQuote('health')",'file')}${btn('Save quote & create lead',"saveQuote('health')",'check',true)}</div></section></div>`}
function quotePlanEditor(index=-1){if(index<0&&quoteDraft.plans.length>=4)return toast('Compare up to 4 plans');let p=quoteDraft.plans[index]||{};modal('Comparison plan',`<form onsubmit="event.preventDefault();saveQuotePlan(this,${index})"><div class="formgrid">${fieldHTML(F('insurer','Insurer','text',true),p.insurer)}${fieldHTML(F('name','Plan name','text',true),p.name)}${fieldHTML(F('brochure','Brochure URL','url'),p.brochure)}${fieldHTML(F('features','Benefits, exclusions and limits (one per line)','textarea'),p.features)}${fieldHTML(F('conditions','Special conditions / waiting periods','textarea'),p.conditions)}</div><p>Use current insurer documents. This workspace does not validate coverage claims.</p><div class="modalfoot"><button class="primary">Save plan</button></div></form>`)}
function saveQuotePlan(form,index){let d=Object.fromEntries(new FormData(form));if(d.brochure&&!/^https:\/\//i.test(d.brochure))return toast('Brochure URL must use HTTPS');let old=quoteDraft.plans[index]||{};let plan={...old,...d,premiums:old.premiums||[0,0,0]};if(index<0)quoteDraft.plans.push(plan);else quoteDraft.plans[index]=plan;saveQuoteDraft();closeModal();render()}
function makeQuoteNote(){quoteDraft.note=`Prepared for ${quoteDraft.customer||'the customer'} with ${quoteDraft.members.length} insured member(s) and requested cover ${quoteDraft.sumInsured}. Compare premiums, exclusions, waiting periods and limits in the current policy documents before choosing a plan.`;saveQuoteDraft();render();toast('Note created from entered data — no AI model used')}
function nivaTotals(matrix=quoteDraft.premiums){return [0,1,2,3,4].map(y=>matrix.reduce((sum,row,i)=>sum+(i>=6?-Math.abs(amount(row[y])):amount(row[y])),0))}
function nivaQuotePage(){return heading('NIVA QUOTE','Niva quote maker','ReAssure 3.0 · enter or review premiums and generate a printable quote.',btn('Saved quotes',"go('savedquotes')",'file'))+`<div class="notice">Screenshot-to-AI extraction is not connected. Uploads stay in this browser; enter and verify the premium components manually.</div><section class="card pad"><h2>Customer details</h2>${quoteCustomerFields()}<h2 class="form-section">Insured members</h2>${quoteMembers()}<h2 class="form-section">Plan configuration</h2><div class="formgrid"><label class="field">Variant<select onchange="quoteField('variant',this.value)">${optionsHTML(['Classic','Select','Elite','Black'],quoteDraft.variant,false)}</select></label><label class="field">PA per adult (₹)<input type="number" min="0" value="${amount(quoteDraft.pa)}" oninput="quoteField('pa',amount(this.value))"></label><label class="field full"><span><input type="checkbox" ${quoteDraft.port?'checked':''} onchange="quoteField('port',this.checked);render()"> This is a port case</span></label>${quoteDraft.port?`<label class="field full">Porting details<textarea oninput="quoteField('portDetails',this.value)">${esc(quoteDraft.portDetails||'')}</textarea></label>`:''}</div><h2 class="form-section">Calculator screenshots</h2><p class="subtle">Up to 8 PNG / JPG images, maximum 10 MB each.</p><input type="file" accept="image/png,image/jpeg" multiple aria-label="Niva calculator screenshots" onchange="saveQuoteScreenshots(this)"><div class="attachment-list">${(quoteDraft.screenshots||[]).map(f=>`<button onclick="downloadAttachment('${f.id}')">${I('file')}${esc(f.name)}</button>`).join('')}</div><h2 class="form-section">Premium components (₹)</h2><div class="tablewrap"><table class="premium-table"><thead><tr><th>Component</th>${[1,2,3,4,5].map(y=>`<th>${y} year${y>1?'s':''}</th>`).join('')}</tr></thead><tbody>${nivaComponents.map((c,i)=>`<tr><th>${c}</th>${[0,1,2,3,4].map(y=>`<td><input type="number" step="0.01" aria-label="${c} ${y+1} year" value="${amount(quoteDraft.premiums[i][y])}" oninput="setNivaPremium(${i},${y},this.value)"></td>`).join('')}</tr>`).join('')}<tr><th>Total payable</th>${nivaTotals().map((v,y)=>`<td id="niva-total-${y}">${rupee(v)}</td>`).join('')}</tr><tr><th>Effective / year</th>${nivaTotals().map((v,y)=>`<td id="niva-effective-${y}">${rupee(Math.round(v/(y+1)))}</td>`).join('')}</tr></tbody></table></div><p class="subtle">Discount rows are automatically subtracted. Values are entered by you, not extracted by AI.</p><div class="modalfoot">${btn('Preview',"previewQuote('niva')",'file')}${btn('Save quote & create lead',"saveQuote('niva')",'check',true)}</div></section>`}
function setNivaPremium(i,y,v){quoteDraft.premiums[i][y]=i>=6?-Math.abs(amount(v)):amount(v);saveQuoteDraft();nivaTotals().forEach((sum,j)=>{document.querySelector('#niva-total-'+j).textContent=rupee(sum);document.querySelector('#niva-effective-'+j).textContent=rupee(Math.round(sum/(j+1)))})}
async function saveQuoteScreenshots(input){try{let files=[...input.files];quoteDraft.screenshots||=[];if(files.length+quoteDraft.screenshots.length>8)throw Error('Maximum 8 screenshots');for(const f of files){if(!['image/png','image/jpeg'].includes(f.type))throw Error('PNG and JPG only');quoteDraft.screenshots.push(await persistFile(f))}saveQuoteDraft();render()}catch(e){saveQuoteDraft();render();toast(e.message)}}
function quoteValidation(q,kind){if(!q.customer.trim())return 'Customer name is required';if(!validPhone(q.phone))return 'Enter a valid 10-digit mobile';if(!q.members.length||q.members.some(m=>!m.name.trim()||m.age===''||amount(m.age)<0||amount(m.age)>120))return 'Enter a name and valid age for every member';if(kind==='health'&&(!q.plans.length||q.plans.some(p=>!p.premiums.some(v=>amount(v)>0))))return 'Enter at least one premium for every selected plan';if(kind==='niva'&&(amount(q.premiums[0][0])<=0||nivaTotals(q.premiums).some(v=>v<0)))return 'Enter a positive 1-year base premium and ensure totals are nonnegative';return ''}
function quotePrintable(q,kind){let memberTable=`<table><thead><tr><th>Name</th><th>Relation</th><th>DOB</th><th>Age</th><th>Medical history</th></tr></thead><tbody>${q.members.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.relation)}</td><td>${esc(m.dob||'')}</td><td>${esc(m.age)}</td><td>${esc(m.ped||'')}</td></tr>`).join('')}</tbody></table>`;let intro=`<p><strong>${esc(q.customer)}</strong> · ${esc(q.phone)} · ${esc(q.city)}</p><p>Quote ref: ${esc(q.reference||'Preview')} · Case: ${esc(q.caseType||'Fresh')}</p>`;let disclaimer='<p class="quote-disclaimer">Prepared using manually entered information. This is not insurer confirmation, a binding quote or insurance advice. Verify premiums and coverage in current insurer documents before purchase.</p>';if(kind==='niva')return `<section class="print-page">${intro}<h2>Niva Bupa · ReAssure 3.0 · ${esc(q.variant)}</h2><h3>Insured members</h3>${memberTable}<p>Requested sum insured: ${esc(q.sumInsured)} · PA per adult: ${rupee(q.pa)}</p>${disclaimer}</section><section class="print-page"><h2>Premium comparison</h2><table><thead><tr><th>Component</th>${[1,2,3,4,5].map(y=>`<th>${y} year</th>`).join('')}</tr></thead><tbody>${nivaComponents.map((c,i)=>`<tr><th>${c}</th>${q.premiums[i].map((v,y)=>`<td>${rupee(i>=6?-Math.abs(amount(v)):amount(v))}</td>`).join('')}</tr>`).join('')}<tr><th>Total</th>${nivaTotals(q.premiums).map(v=>`<td>${rupee(v)}</td>`).join('')}</tr></tbody></table>${disclaimer}</section><section class="print-page"><h2>Porting details & advisor note</h2><p>Port case: ${q.port?'Yes':'No'}</p><p>${esc(q.portDetails||'Not entered')}</p><p>${esc(q.note||'No advisor note entered.')}</p>${disclaimer}</section><section class="print-page"><h2>Documents & next steps</h2><p>${(q.screenshots||[]).map(f=>esc(f.name)).join('<br>')||'No source screenshots attached.'}</p><p>Advisor: ${esc(workspace.profile.name)} · ${esc(workspace.profile.phone||'')}</p><p>Review the complete policy wording and ask the insurer to confirm all benefits, waiting periods, exclusions and final payable premium.</p>${disclaimer}</section>`;return `${intro}<h2>Insured members</h2>${memberTable}<h2>Plan comparison</h2><table><thead><tr><th>Plan</th><th>Sum assured</th><th>1 year</th><th>2 years</th><th>3 years</th></tr></thead><tbody>${q.plans.map(p=>`<tr><td>${esc(p.insurer)} · ${esc(p.name)}</td><td>${esc(p.sumInsured||q.sumInsured)}</td>${p.premiums.map(v=>`<td>${amount(v)>0?rupee(v):'—'}</td>`).join('')}</tr>`).join('')}</tbody></table><h2>Benefits, limits & conditions</h2>${q.plans.map(p=>`<section><h3>${esc(p.insurer)} · ${esc(p.name)}</h3><p class="pre-line">${esc(p.features||'No feature details entered.')}</p><p>${esc(p.conditions||'')}</p>${p.brochure&&/^https:\/\//i.test(p.brochure)?`<p>Brochure: ${esc(p.brochure)}</p>`:''}</section>`).join('')}<h2>Advisor note</h2><p>${esc(q.note||'No note entered.')}</p>${disclaimer}`}
function previewQuote(kind){modal('Quote preview',`<div class="quote-preview">${quotePrintable(quoteDraft,kind)}</div><div class="modalfoot">${btn('Print / Save as PDF',`printDocument('Insurance quote',quotePrintable(quoteDraft,'${kind}'))`,'download',true)}</div>`)}
function saveQuote(kind){let error=quoteValidation(quoteDraft,kind);if(error)return toast(error);let q={...structuredClone(quoteDraft),kind,id:uid('QUOTE'),createdAt:new Date().toISOString()};workspace.quotes.unshift(q);let lead=db.leads.find(l=>normalisePhone(l.phone)===normalisePhone(q.phone)&&['Health','Niva Quote'].includes(l.product));if(lead){lead.status='Quote given';lead.quoteId=q.id}else db.leads.unshift({id:uid('LEAD'),name:q.customer,phone:normalisePhone(q.phone),city:q.city,product:'Health',status:'Quote given',date:dateISO(),quoteId:q.id,premium:kind==='niva'?nivaTotals(q.premiums)[0]:amount(q.plans[0]?.premiums[0])});save();saveWorkspace();toast('Quote and lead saved locally');go('savedquotes')}
function savedQuotesPage(){return heading('QUOTES','Saved quotes','Open your saved quote documents.',btn('Health quote',"go('quotes')",'plus',true)+btn('Niva quote',"go('nivaquote')",'plus'))+`<section class="card tablewrap"><table><thead><tr><th>Customer</th><th>Type</th><th>Created</th><th>Action</th></tr></thead><tbody>${workspace.quotes.map(q=>`<tr><td>${esc(q.customer)}</td><td>${q.kind==='niva'?'Niva':'Health comparison'}</td><td>${esc(q.createdAt.slice(0,10))}</td><td>${btn('Preview',`openSavedQuote('${q.id}')`,'file')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No saved quotes</td></tr>'}</tbody></table></section>`}
function openSavedQuote(id){let q=workspace.quotes.find(q=>q.id===id);modal('Saved quote',`<h3>${esc(q.customer)}</h3><p>${esc(q.id)}</p><div class="modalfoot">${btn('Print / Save PDF',`printSavedQuote('${id}')`,'download',true)}${btn('Edit copy',`editSavedQuote('${id}')`,'file')}</div>`)}
function printSavedQuote(id){let q=workspace.quotes.find(q=>q.id===id);printDocument('Insurance quote',quotePrintable(q,q.kind))}
function editSavedQuote(id){quoteDraft=structuredClone(workspace.quotes.find(q=>q.id===id));saveQuoteDraft();closeModal();go(quoteDraft.kind==='niva'?'nivaquote':'quotes')}
